from fastapi import FastAPI
from pydantic import BaseModel
app=FastAPI()
class Todo(BaseModel):
    title:str
    done:bool=False
todos=[]
@app.post('/todos')
def create(todo:Todo):
    todos.append(todo)
    return todo
@app.get('/todos')
def list_all(done:bool=None):
    if done is None:return todos
    return [t for t in todos if t.done==done]

class Book(Base):
    __tablename__='books'
    id=Column(Integer,primary_key=True)
    title=Column(String,nullable=False)
    author=Column(String)
@app.get('/books')
def list_books(page:int=1,size:int=10):
    offset=(page-1)*size
    books=db.query(Book).offset(offset).limit(size).all()
    return books

import requests,time
from bs4 import BeautifulSoup
def crawl(url,max_retries=3,delay=1):
    for attempt in range(max_retries):
        try:
            r=requests.get(url,timeout=10,headers={'User-Agent':'Mozilla/5.0'})
            r.raise_for_status()
            return BeautifulSoup(r.text,'html.parser')
        except Exception as e:
            if attempt==max_retries-1:raise
            time.sleep(delay*(2**attempt))

